function sum2(n) {
    if (n < 0) return 0n;
    const x = BigInt(n);
    return x * (x + 1n) * (2n * x + 1n) / 6n;
}

function countInvalid(x, y, z) {
    const k = y + z - x;
    let result = 0n;

    const hi1 = Math.min(l, -k);
    if (hi1 >= 0) {
        const n = BigInt(hi1 + 1);
        const s1 = sum1(hi1);
        const s2 = sum2(hi1);
        result += BigInt(l) * s1 + BigInt(l + 1) * n - s2;
    }

    const lo2 = Math.max(0, -k + 1);
    const hi2 = Math.min(l, Math.floor((l - k) / 2));

    if (lo2 <= hi2) {
        const n = BigInt(hi2 - lo2 + 1);
        const s1 = sum1(hi2) - sum1(lo2 - 1);
        const s2 = sum2(hi2) - sum2(lo2 - 1);
        const m = BigInt(l - k + 1);

        result += (m - 2n) * s1 + m * n - 2n * s2;
    }

    return result;
